arregla esto:
func Suma(xs []int) int {
	total := 0
	for i := 0; i < xs.length; i++ {
		total += xs[i]
	}
	return total
}

arregla esta función: debería dar el máximo, pero con [3,1,2] da 1; con [3,1,2] debería dar 3
func Maximo(xs []int) int {
	m := xs[0]
	for _, x := range xs {
		if x < m {
			m = x
		}
	}
	return m
}

me sale index out of range:
func Suma(xs []int) int {
	total := 0
	for i := 0; i <= len(xs); i++ {
		total += xs[i]
	}
	return total
}

